}

Method.Source:
void setCSDId()
{
    NDXCSDId cSDId;
    ExtendedTypeId idNDXCSDId = extendedtypenum(NDXCSDId);
    NumberSeq num;

    num = NumberSeq::newGetNum(NumberSeqReference::findReference(idNDXCSDId));

    cSDId = num.num();

    this.CSDId  = cSDId;
    num.used();
}

/// <summary>
/// Creates NDX_CentralStoreDistributionTable record
/// </summary>
/// <param name = "_nDX_CentralStoreDistributionTable">NDX_CentralStoreDistributionTable record</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDX_CentralStoreDistributionTable record</returns>
server static public NDX_CentralStoreDistributionTable create(NDX_CentralStoreDistributionTable _nDX_CentralStoreDistributionTable, boolean _forUpdate = false)
{
    NDX_CentralStoreDistributionTable      nDX_CentralStoreDistributionTable;

    if (_forUpdate)
    {
        nDX_CentralStoreDistributionTable.selectForUpdate(_forUpdate);
    }

    nDX_CentralStoreDistributionTable.initValue();
    nDX_CentralStoreDistributionTable.ValidFrom          = _nDX_CentralStoreDistributionTable.ValidFrom;
    nDX_CentralStoreDistributionTable.CentralStoreId     = _nDX_CentralStoreDistributionTable.CentralStoreId;

    return nDX_CentralStoreDistributionTable;
}

/// <summary>
/// finds or creates NDX_CentralStoreDistributionTable record
/// </summary>
/// <param name = "_NDX_CentralStoreDistributionTable">NDX_CentralStoreDistributionTable record</param>
/// <param name = "_forUpdate">forupdate</param>
/// <returns>NDX_CentralStoreDistributionTable record</returns>
client server static public NDX_CentralStoreDistributionTable findOrCreate(NDX_CentralStoreDistributionTable _NDX_CentralStoreDistributionTable, boolean _forUpdate = false)
{
    NDX_CentralStoreDistributionTable  nDX_CentralStoreDistributionTable;
    ;
    nDX_CentralStoreDistributionTable = NDX_CentralStoreDistributionTable::findCS(_NDX_CentralStoreDistributionTable, _forUpdate);
    if (!nDX_CentralStoreDistributionTable)
    {
        nDX_CentralStoreDistributionTable = NDX_CentralStoreDistributionTable::create(_NDX_CentralStoreDistributionTable, _forUpdate);
    }

    return nDX_CentralStoreDistributionTable;
}

/// <summary>
/// finds NDX_CentralStoreDistributionTable record
/// </summary>
/// <param name = "_nDX_CentralStoreDistributionTable">NDX_CentralStoreDistributionTable record</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDX_CentralStoreDistributionTable record</returns>
client server static public NDX_CentralStoreDistributionTable findCS(NDX_CentralStoreDistributionTable _nDX_CentralStoreDistributionTable, boolean _forUpdate = false)
{
    NDX_CentralStoreDistributionTable      nDX_CentralStoreDistributionTable;

    if (_forUpdate)
    {
        nDX_CentralStoreDistributionTable.selectForUpdate(_forUpdate);
    }

    select firstOnly    nDX_CentralStoreDistributionTable
        where nDX_CentralStoreDistributionTable.ValidFrom == _nDX_CentralStoreDistributionTable.ValidFrom
            && nDX_CentralStoreDistributionTable.CentralStoreId     == _nDX_CentralStoreDistributionTable.CentralStoreId;

    return nDX_CentralStoreDistributionTable;
}

/// <summary>
/// DebuC 21.09.23
/// </summary>
/// <param name = "centralStoreId">NDXCentralStoreId</param>
/// <param name = "jahr">int</param>
/// <param name = "conCompanies">Container</param>
/// <param name = "lInfo">boolean</param>
/// <returns>NDX_CentralStoreDistributionTable</returns>
client server static public NDX_CentralStoreDistributionTable findCSYearBest(NDXCentralStoreId centralStoreId,
                                                                         int  jahr         = year(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))-1,
                                                                         Container          conCompanies = [curExt()],
                                                                         boolean            lInfo        = true)
{
    NDX_CentralStoreDistributionTable      centralStoreDistributionTable;
    NDX_CentralStoreDistributionTable      centralStoreDistributionTableNear;
    NDX_CentralStoreDistributionTable      centralStoreDistributionTableActive;
    ;

    // Versuch, Daten zum angeforderten Abschlussjahr zu ermitteln
    centralStoreDistributionTable = NDX_CentralStoreDistributionTable::findCSYear(centralStoreId, jahr, conCompanies);
    if (centralStoreDistributionTable)  // Treffer
    {
        return centralStoreDistributionTable;
    }
    // handelt es sich überhaut um ein Zentrallager?
    if (!NDX_CentralStore::findConCompany(centralStoreId, conCompanies))
    {
        return centralStoreDistributionTable;
    }
    // Ermittlung des zum angeforderten Abschlussjahr nächstliegene Set
    centralStoreDistributionTableNear   = NDX_CentralStoreDistributionTable::findCSYearNear(centralStoreId, jahr, conCompanies);

    // falls das Anforderungsjahr <= dem ermittelten Abschlussjahr ist, kann das Set genutzt werden
    if (jahr <= centralStoreDistributionTableNear.AbschlussJahr)    // bestmögliches gültiges Abschlussjahr
    {
        if (lInfo)
        {
            info(strfmt("@NDX:NDXCSDInfo1", curExt(), centralStoreId, jahr, centralStoreDistributionTableNear.AbschlussJahr));      // (01) UK [%1] ZL [%2] Jahr [%3] - Bestmögliches Set mit Abschlussjahr [%4] ermittelt
        }
        return centralStoreDistributionTableNear;
    }

    // jetzt kann nur noch das aktive Erfassungsset zurückgegeben werden
    centralStoreDistributionTableActive = NDX_CentralStoreDistributionTable::findCSAktive(centralStoreId, conCompanies);
    if (year(centralStoreDistributionTableActive.ValidFrom) >= jahr)
    {
        // (02) UK [%1] ZL [%2] Jahr [%3] - Kein DS mit diesem Abschlussjahr ermittelt. Rückgabe aktives Set mit Gültigkeitsdatum ab [%4]
        if (lInfo)
        {
            info(strfmt("@NDX:NDXCSDInfo2", curext(), centralStoreId, jahr, centralStoreDistributionTableActive.ValidFrom));
        }
        return centralStoreDistributionTableActive;
    }
    else
    {
        // (03) UK [%1] ZL [%2] Jahr [%3] - Kein DS mit diesem Abschlussjahr ermittelt. Rückgabe aktives Set mit Gültigkeitsdatum ab [%4]
        if (lInfo)
        {
            info(strfmt("@NDX:NDXCSDInfo3", curext(), centralStoreId, jahr, centralStoreDistributionTableActive.ValidFrom));
        }
        return centralStoreDistributionTableActive;

    }
}

/// <summary>
/// DebuC 21.09.23
/// </summary>
/// <param name = "centralStoreId">NDXCentralStoreId</param>
/// <param name = "conCompanies">Container</param>
/// <returns>NDX_CentralStoreDistributionTable</returns>
client server static public NDX_CentralStoreDistributionTable findCSAktive(NDXCentralStoreId centralStoreId, Container conCompanies = [curExt()])
{
    NDX_CentralStoreDistributionTable      centralStoreDistributionTable;
    ;

    select crosscompany:conCompanies
                centralStoreDistributionTable
        where   centralStoreDistributionTable.CentralStoreId    == centralStoreId &&
                centralStoreDistributionTable.Aktiv             == NoYes::Yes;

    return centralStoreDistributionTable;
}

/// <summary>
/// DebuC 26.02.24
/// </summary>
/// <param name = "centralStoreId">NDXCentralStoreId</param>
/// <param name = "jahr">int</param>
/// <param name = "conCompanies">Container</param>
/// <returns>NDX_CentralStoreDistributionTable</returns>
client server static public NDX_CentralStoreDistributionTable findCSYear(NDXCentralStoreId centralStoreId,
                                                                     int  jahr         = year(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))-1,
                                                                     Container          conCompanies = [curExt()])
{
    NDX_CentralStoreDistributionTable      centralStoreDistributionTable;
    ;
    select crosscompany:conCompanies
                centralStoreDistributionTable
        where   centralStoreDistributionTable.CentralStoreId    == centralStoreId &&
                centralStoreDistributionTable.AbschlussJahr     == jahr;

    return centralStoreDistributionTable;
}

/// <summary>
/// DebuC 26.02.24
/// </summary>
/// <param name = "centralStoreId">NDXCentralStoreId</param>
/// <param name = "jahr">int</param>
/// <param name = "conCompanies">Container</param>
/// <returns>NDX_CentralStoreDistributionTable</returns>
client server static public NDX_CentralStoreDistributionTable findCSYearNear(NDXCentralStoreId centralStoreId,
                                                                         int  jahr         = year(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))-1,
                                                                         Container          conCompanies = [curExt()])
{
    NDX_CentralStoreDistributionTable      centralStoreDistributionTable;
    ;
    select firstonly crosscompany:conCompanies
                    centralStoreDistributionTable
        order by    centralStoreId, AbschlussJahr desc
        where       centralStoreDistributionTable.CentralStoreId    == centralStoreId &&
                    centralStoreDistributionTable.AbschlussJahr     <= Jahr;

    return centralStoreDistributionTable;
}

void setCSDPct()
{
    NDX_CentralStoreDistributionLine    LineSum, Line;

    // Preissumme
    select      sum(CSDPrice)
    from    LineSum
    where   LineSum.CSDId   == this.CSDId;

    if (LineSum.CSDPrice)
    {
        ttsbegin;
        while select forUpdate Line
            where line.CSDId == this.CSDId
        {
            line.CSDPct = (Line.CSDPrice * 100 / LineSum.CSDPrice);
            line.update();
        }
        ttscommit;
    }
}

public void update()
{
    NDX_CentralStoreDistributionTable lNDX_CentralStoreDistributionTable;

    if(this.Aktiv && this.orig().Aktiv != this.Aktiv)
    {
        select forupdate lNDX_CentralStoreDistributionTable
            where lNDX_CentralStoreDistributionTable.CentralStoreId == this.CentralStoreId
                && lNDX_CentralStoreDistributionTable.Aktiv
                && lNDX_CentralStoreDistributionTable.RecId != this.RecId;

        if(lNDX_CentralStoreDistributionTable)
        {
            lNDX_CentralStoreDistributionTable.Aktiv = false;
            lNDX_CentralStoreDistributionTable.doUpdate();
        }
    }
    super();
}
